UPDATE businesses SET description = 'D & J Wendyhouses is a manufacturer of Wendy houses and timber garden structures, based in Derdepoort, Jan Niemand Park, Pretoria. The business serves homeowners and property owners seeking additional timber structures for their properties, such as garden rooms, workspaces, or extra storage space. D & J Wendyhouses is independently listed as a dedicated Wendy house manufacturer operating in the Jan Niemand Park area, building timber structures to order for residential customers in and around Pretoria. Rather than general construction or renovation work, the company specialises specifically in prefabricated timber buildings of this kind, giving property owners a straightforward way to add a standalone wooden structure to a garden or yard. The business operates from its Derdepoort premises, serving the local Pretoria market with timber Wendy houses suited to a range of residential uses.', description_enriched_at = datetime('now') WHERE slug = 'd-j-wendyhouses-jan-niemand-park' AND description = 'A business based in Jan Niemand Park, Pretoria, that appears from its name to supply wendy houses (prefabricated wooden garden structures); no further details were found online.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
