-- der-zucker-backer-menlyn (owner)
UPDATE businesses SET description = 'Der Zucker Backer is a German bakery and coffee shop located in Menlyn Retail Park, on the corner of Garsfontein Road and Lois Avenue, Pretoria. The business has been associated with Pretoria since the early 1990s, having previously operated in Hazelwood before relocating to its current Menlyn Retail Park premises. Der Zucker Backer specialises in German-style baked goods, pastries and cakes, alongside coffee, breakfast and light meals, serving individuals, families and diners looking for authentic German bakery fare. Its signature offering is the Bienenstich, or bee-sting pastry, alongside a wider range of German confectionery and baked treats. Customers can visit for a sit-down breakfast or light meal, or call in for coffee and pastries to enjoy on site or take away. With roots going back more than three decades in Pretoria, Der Zucker Backer continues to serve the Menlyn area from its Garsfontein Road and Lois Avenue location.', description_enriched_at = datetime('now') WHERE slug = 'der-zucker-backer-menlyn' AND description = 'A German bakery and cafe in Menlyn Retail Park known for traditional German pastries and cakes, including its Bienenstich (bee sting cake), offering dine-in, takeout and delivery.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
