-- door-2-door-digital-cc-waverley (owner)
UPDATE businesses SET description = 'Door 2 Door Digital CC is a digital printing and signwriting business operating from 1309 Starkey Avenue, Waverley, Pretoria, with roots dating back to 2006. The company provides digital printing services, signwriting artistry, and sign-making materials to individuals and businesses in need of signage and printed vinyl products. Its offering spans the design and production of signage as well as supply of sign-related materials, making it a one-stop option for businesses wanting branded signage, vehicle graphics, or other printed vinyl work. Customer feedback has particularly highlighted the quality of its vinyl products, pointing to consistent standards in the printing and material side of the business. Having operated in Waverley since 2006, Door 2 Door Digital CC has built up nearly two decades of experience in the digital printing and signwriting trade, serving the Pretoria area with both the practical printing side of signage production and the more creative, artistic side of signwriting design.', description_enriched_at = datetime('now') WHERE slug = 'door-2-door-digital-cc-waverley' AND description = 'Door 2 Door Digital CC is a Pretoria-based supplier of premium large-format print media for eco-solvent, latex and UV print technologies, operating from Starkey Ave in Waverley.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
