UPDATE businesses SET description = 'Durand M C is the medical practice of Dr Michiel Christoffel Durand, a general surgeon practising in Pretoria. The practice is based at Suite 16, Doctors Village, within the Life Eugene Marais Hospital complex in Les Marais, Pretoria. Dr Durand is listed by Life Healthcare as a general surgeon, and the practice serves patients requiring general surgical consultation and treatment. Operating from within a hospital-based doctors'' village gives patients access to surgical consultation in close proximity to the hospital''s broader theatre and inpatient facilities. As a general surgical practice, Durand M C serves the surrounding Pretoria community, including Les Marais and nearby suburbs, for patients needing to consult a general surgeon ahead of or following a procedure. Patients can find the practice at its Suite 16 rooms within the Doctors Village attached to Life Eugene Marais Hospital, one of several specialist practices operating from that address.', description_enriched_at = datetime('now') WHERE slug = 'durand-m-c-les-marais' AND description = 'Durand M C is the practice of Dr Michiel Christoffel Durand, a surgeon consulting from Suite 16, Doctors Village at Eugene Marais Hospital in Les Marais, Pretoria.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
