UPDATE businesses SET description = 'EST Sourcing (Pty) Ltd is a bursary, learnership and corporate social investment (CSI) management company headquartered in the City of Tshwane, founded in 2021. The company works with corporate partners and public and private education institutions to administer bursary and education funding programmes, helping disadvantaged students and youth access financial support for their studies. For corporate clients, EST Sourcing manages programmes that contribute toward enterprise and supplier development, as well as training-related B-BBEE scorecard points, linking social investment spend to measurable compliance outcomes. Its services bring together corporates seeking to meet B-BBEE and CSI obligations, educational institutions needing funding partners, and students and young people in need of bursary or learnership support. EST Sourcing continues to administer bursary funding in partnership with municipalities and corporate partners, positioning itself as an intermediary between funders and the students who benefit from their contributions. The company operates from Moreleta Park, Pretoria, serving clients across the broader Tshwane area and beyond.', description_enriched_at = datetime('now') WHERE slug = 'est-sourcing-pty-ltd-wingate-park' AND description = 'EST Sourcing (Pty) Ltd is a Pretoria-based sourcing and procurement consultancy in Moreleta Park, working with companies on sourcing services and also offering bursary opportunities for students.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
