-- fargomax-pty-ltd-heuweloord (owner)
UPDATE businesses SET description = 'Fargomax (Pty) Ltd is an IT services company founded in 2011 that implements, customises, integrates, and maintains SAP Business One ERP systems for small and medium-sized businesses. Its SAP Business One work covers finance, purchasing, inventory, sales, customer relationship management (CRM), projects and operations, and human resources modules, with ongoing user support once systems are live. Alongside its ERP work, Fargomax provides Bluwave integration and support, cybersecurity services, IT consulting, technical maintenance and user training. The company serves SMEs looking to automate business processes and streamline operations across departments, offering a single point of contact from initial ERP implementation through to long-term maintenance and support. Fargomax is a small team of between two and ten people, based in the Centurion area, reflecting a focused, specialist consultancy model rather than a large-scale IT vendor. Its combination of ERP implementation, cybersecurity and general IT consulting positions it as a one-stop technology partner for SMEs needing both software systems and broader IT support.', description_enriched_at = datetime('now') WHERE slug = 'fargomax-pty-ltd-heuweloord' AND description = 'Fargomax is an SAP Business One implementation partner that has provided ERP, business intelligence and related IT solutions to small and medium-sized businesses for over 15 years.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
