UPDATE businesses SET description = 'Flight Centre The Grove Pretoria is a travel agency branch located at Shop L03, The Grove Shopping Centre, on the corner of Lynnwood Road and Simon Vermooten Road in Die Wilgers, Pretoria. As a dedicated travel-agency branch within The Grove, it provides flight bookings, accommodation bookings, tours and customised holiday itineraries to customers. The branch serves holidaymakers, families, business travellers and individuals planning trips, offering in-person travel consultations for both leisure and business travel needs. Customers can book flights and accommodation separately or put together full travel packages, including guided and independent tours, tailored to their specific destinations and travel dates. Being based inside The Grove Shopping Centre gives shoppers in Die Wilgers and the surrounding Pretoria East area convenient access to a full-service travel agency while going about other errands at the centre. As part of the wider Flight Centre network, the branch draws on established travel-industry relationships to help plan and book trips of varying complexity, from simple flight bookings to multi-destination holiday itineraries.', description_enriched_at = datetime('now') WHERE slug = 'flight-centre-the-grove-pretoria-de-wilgers' AND description = 'Flight Centre The Grove Pretoria is a travel agency branch inside The Grove Shopping Centre in Die Wilgers, offering flight bookings, accommodation, tours and tailored holiday itineraries.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
